<?php declare(strict_types=1); ?>
<section class="panel customer-list-panel"><form class="filter-bar audit-filter"><input type="hidden" name="page" value="audit"><input name="q" value="<?= kd_e($q) ?>" placeholder="İşlem, IP veya kayıt türü"><input name="action" value="<?= kd_e($action) ?>" placeholder="İşlem adı"><select name="entity"><option value="">Tüm kayıt türleri</option><?php foreach(['customer','product','order','invoice','employee','user','settings','license','system_backup'] as $e): ?><option value="<?= kd_e($e) ?>" <?= $entity===$e?'selected':'' ?>><?= kd_e($e) ?></option><?php endforeach; ?></select><select name="user_id"><option value="0">Tüm kullanıcılar</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>" <?= $userId===(int)$u['id']?'selected':'' ?>><?= kd_e($u['name']) ?></option><?php endforeach; ?></select><input type="date" name="from" value="<?= kd_e($from) ?>"><input type="date" name="to" value="<?= kd_e($to) ?>"><button class="btn secondary">Filtrele</button></form><div class="panel-head"><h3>İşlem geçmişi</h3><span class="result-count"><?= $total ?> kayıt</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Kullanıcı</th><th>İşlem</th><th>Kayıt türü</th><th>Kayıt ID</th><th>IP adresi</th><th>Tarayıcı</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= kd_e($l['created_at']) ?></td><td><?= kd_e($l['user_name']??'Sistem') ?><small class="table-sub"><?= kd_e($l['user_email']??'') ?></small></td><td><strong><?= kd_e($l['action']) ?></strong></td><td><?= kd_e($l['entity_type']??'—') ?></td><td><?= kd_e($l['entity_id']??'—') ?></td><td><?= kd_e($l['ip_address']??'—') ?></td><td><?= kd_e(mb_substr($l['user_agent']??'',0,65)) ?></td></tr><?php endforeach; ?><?php if(!$logs): ?><tr><td colspan="7">Filtreye uygun kayıt yok.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><span>Sayfa <?= $page ?> / <?= $pages ?></span><?php if($page>1): ?><a href="<?= kd_e('index.php?'.http_build_query(array_merge($_GET,['p'=>$page-1]))) ?>">Önceki</a><?php endif; ?><?php if($page<$pages): ?><a href="<?= kd_e('index.php?'.http_build_query(array_merge($_GET,['p'=>$page+1]))) ?>">Sonraki</a><?php endif; ?></div></section>
